@page "/courses"
@rendermode InteractiveServer
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-5 mb-2">
        <input type="text" class="form-control" placeholder="Search courses, instructors…"
               @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3 mb-2">
        <select class="form-select" @bind="SelectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 mb-2">
        <select class="form-select" @bind="SelectedCredits">
            <option value="0">Any Credits</option>
            <option value="3">3 Credits</option>
            <option value="4">4 Credits</option>
        </select>
    </div>
    <div class="col-md-2 mb-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@if (_filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_filteredCourses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-hover">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _filteredCourses)
                {
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor.Name</td>
                        <td><small>@course.Schedule</small></td>
                        <td>
                            <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> _departments = [];
    private List<Course> _filteredCourses = [];

    private string _searchTerm = "";
    private int _selectedDepartmentId;
    private int _selectedCredits;

    private string SearchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int SelectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    private int SelectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; ApplyFilters(); }
    }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();

        if (DepartmentId.HasValue)
        {
            _selectedDepartmentId = DepartmentId.Value;
        }

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        int? minCredits = _selectedCredits > 0 ? _selectedCredits : null;
        int? maxCredits = _selectedCredits > 0 ? _selectedCredits : null;

        _filteredCourses = Catalog.GetCourses(
            searchTerm: string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            departmentId: deptFilter,
            minCredits: minCredits,
            maxCredits: maxCredits);
    }

    private void ClearFilters()
    {
        _searchTerm = "";
        _selectedDepartmentId = 0;
        _selectedCredits = 0;
        ApplyFilters();
    }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
            <strong>@Catalog.GetCourseDisplayName(_model.CourseId)</strong> has been received.</p>
        <p class="mb-0">You will receive a confirmation at <strong>@_model.Email</strong> once your request is processed.</p>
    </div>
    <a href="/enroll" class="btn btn-primary me-2">Submit Another Request</a>
    <a href="/courses" class="btn btn-outline-secondary">Browse Courses</a>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card">
                <div class="card-body">
                    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                        <DataAnnotationsValidator />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <InputText id="fullName" class="form-control" @bind-Value="_model.FullName" />
                            <ValidationMessage For="() => _model.FullName" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g., STU123456" />
                            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="email" class="form-label">Email Address <span class="text-danger">*</span></label>
                            <InputText id="email" class="form-control" @bind-Value="_model.Email" type="email" />
                            <ValidationMessage For="() => _model.Email" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                                <option value="0">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    <option value="@course.Id">@course.Code – @course.Title (@course.Credits cr.)</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="notes" class="form-label">Additional Notes</label>
                            <InputTextArea id="notes" class="form-control" @bind-Value="_model.Notes" rows="3" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </EditForm>
                </div>
            </div>
        </div>
        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">Enrollment Information</h5>
                    <ul class="mb-0">
                        <li>Enrollment requests are reviewed within 2 business days.</li>
                        <li>You will receive a confirmation email once processed.</li>
                        <li>Contact the Registrar's Office at <strong>registrar@university.edu</strong> with questions.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> _courses = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
}

